mapper.select:
SELECT 



 ORDER BY ${sortColumn} ${sortDirection}, o.outbound_seq DESC

    LIMIT #{size} OFFSET #{offset}

SELECT COALESCE(SUM(p.picked_qty), 0)
  FROM tb_outbound_pick p
 WHERE p.line_seq  = #{lineSeq}
   AND p.stock_seq = #{stockSeq}

mapper.update:
UPDATE tb_outbound_line
   SET picked_qty = picked_qty + #{qty}
 WHERE line_seq = #{lineSeq}
   AND picked_qty + #{qty} >= 0
   AND picked_qty + #{qty} + shortage_qty <= instructed_qty

UPDATE tb_outbound_line
   SET shortage_qty    = shortage_qty + #{qty},
       shortage_reason = #{reason}
 WHERE line_seq = #{lineSeq}
   AND picked_qty + shortage_qty + #{qty} <= instructed_qty

sql.where:
AND ol.shortage_qty > 0 AND o.outbound_status <> 'CANCELED'
AND (o.outbound_no ILIKE '%' || #{keyword} || '%' OR so.order_no ILIKE '%' || #{keyword} || '%' OR k.sku_id ILIKE '%' || #{keyword} || '%' OR pr.product_name ILIKE '%' || #{keyword} || '%')
AND pl.plant_id = #{plantId}
AND ol.shortage_reason LIKE #{reasonCode} || '%'
AND o.instructed_at >= #{fromDate}
AND o.instructed_at < (#{toDate}::date + 1)
AND o.instructed_by = #{scope.ownerId}
AND ( pl.org_seq IN
#{org}
OR o.instructed_by = #{scope.ownerId} )

mapper.select:
SELECT o.outbound_seq AS outboundSeq, o.outbound_no AS outboundNo, o.outbound_status AS outboundStatus, ol.line_seq AS lineSeq, ol.line_no AS lineNo, so.order_no AS orderNo, so.receiver_name AS receiverName, pl.plant_id AS plantId, pl.plant_name AS plantName, k.sku_id AS skuId, k.color_code AS colorCode, k.size_code AS sizeCode, pr.product_name AS productName, ol.instructed_qty AS instructedQty, ol.picked_qty AS pickedQty, ol.shortage_qty AS shortageQty, ol.shortage_reason AS shortageReason, (SELECT CASE WHEN COUNT(DISTINCT lo.location_seq) > 1 THEN MIN(lo.location_id) || ' 외 ' || (COUNT(DISTINCT lo.location_seq) - 1) || '곳' ELSE MIN(lo.location_id) END FROM tb_stock_alloc a JOIN tb_stock s ON s.stock_seq = a.stock_seq JOIN tb_location lo ON lo.location_seq = s.location_seq WHERE a.order_line_seq = ol.order_line_seq) AS locationHint, au.user_name AS assignedToName, o.instructed_at AS instructedAt
ORDER BY o.instructed_at DESC, ol.line_no
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE tb_outbound_line
   SET inspected_qty = inspected_qty + #{qty}
 WHERE line_seq = #{lineSeq}
   AND inspected_qty + #{qty} >= 0
   AND inspected_qty + #{qty} <= picked_qty

mapper.select:
SELECT COALESCE(MAX(b.box_no), 0) + 1
  FROM tb_pack_box b
 WHERE b.outbound_seq = #{outboundSeq}

mapper.delete:
DELETE FROM tb_pack_box b
 WHERE b.box_seq = #{boxSeq}
   AND NOT EXISTS (SELECT 1 FROM tb_pack_box_line bl WHERE bl.box_seq = b.box_seq)

mapper.select:
SELECT bl.box_line_seq, bl.box_seq, bl.line_seq, bl.packed_qty,
       bl.packed_by, bl.packed_at
  FROM tb_pack_box_line bl
 WHERE bl.box_seq  = #{boxSeq}
   AND bl.line_seq = #{lineSeq}

mapper.update:
UPDATE tb_pack_box_line
   SET packed_qty = packed_qty + #{qty}
 WHERE box_line_seq = #{boxLineSeq}
   AND packed_qty + #{qty} > 0

mapper.select:
SELECT COALESCE(SUM(bl.packed_qty), 0)
  FROM tb_pack_box_line bl
 WHERE bl.line_seq = #{lineSeq}
